import '../../features/privacy/domain/privacy_checklist.dart';

/// Русские рекомендации по конфиденциальности, привязанные к стабильным ID.
class RussianPrivacyContent {
  RussianPrivacyContent._();
  static const Map<String, Map<String,String>> _data = {
    'account-unique-passwords': {'title':'Используйте уникальные пароли для важных аккаунтов','why':'Повторное использование пароля означает, что утечка в одном сервисе может поставить под угрозу и другие ваши аккаунты.','action':'Используйте надёжный менеджер паролей, чтобы создавать длинный отдельный пароль для каждого важного аккаунта. Защитите менеджер мастер-паролем и настройте доступные способы восстановления.','limit':'Менеджер паролей не защитит аккаунт, если скомпрометированы мастер-пароль или канал восстановления.'},
    'account-mfa': {'title':'Включите многофакторную аутентификацию','why':'Дополнительный фактор снижает последствия кражи пароля.','action':'Включите MFA для почты, финансовых, облачных и социальных аккаунтов. По возможности используйте ключи доступа или аппаратные ключи безопасности и защитите резервные копии приложения-аутентификатора.','limit':'Методы MFA различаются по уровню защиты. SMS-коды подвержены атакам с подменой SIM-карты и переносом номера.'},
    'account-recovery': {'title':'Проверьте способы восстановления аккаунтов','why':'Устаревший адрес почты или номер для восстановления может помешать законному возврату доступа либо облегчить захват аккаунта.','action':'Проверьте резервные адреса, номера телефонов, резервные коды и доверенные устройства в официальных настройках безопасности каждого сервиса.','limit':'Настройки восстановления зависят от сервиса. ORVIKA не может проверить, применил ли поставщик ваши изменения.'},
    'device-updates': {'title':'Обновляйте операционные системы и приложения','why':'Обновления часто исправляют уязвимости, которыми иначе могут воспользоваться злоумышленники.','action':'По возможности включите автоматические обновления безопасности. Устанавливайте обновления через встроенный механизм устройства или официальный магазин приложений.','limit':'Обновление снижает известные риски, но не гарантирует отсутствие компрометации устройства.'},
    'device-lock': {'title':'Защитите устройство надёжной блокировкой экрана','why':'Потерянное или оставленное без присмотра разблокированное устройство может раскрыть сообщения, аккаунты и сохранённые данные.','action':'Используйте длинный PIN-код или пароль, установите короткий интервал автоблокировки; биометрию применяйте как удобный дополнительный способ разблокировки.','limit':'Биометрия и параметры блокировки зависят от устройства. Блокировка экрана не обязательно шифрует все внешние резервные копии.'},
    'device-backups': {'title':'Проверьте резервное копирование и поиск устройства','why':'Резервные копии помогают восстановлению, а функции поиска позволяют найти или удалённо защитить потерянное устройство.','action':'Проверьте, какие данные копируются, кто имеет доступ к аккаунту резервного копирования, доступно ли шифрование копий и включены ли поиск устройства и удалённая блокировка.','limit':'Доступность и настройки шифрования зависят от ОС и поставщика. Сверяйтесь с актуальной документацией.'},
    'apps-permissions': {'title':'Проверяйте разрешения приложений','why':'Приложения могут сохранять доступ к геолокации, контактам, камере, микрофону, фото или устройствам поблизости сверх необходимого.','action':'Откройте системные настройки конфиденциальности или разрешений приложений. Отзовите ненужный доступ; где возможно, выбирайте разовый доступ или доступ только во время использования.','limit':'Названия и элементы управления разрешениями зависят от ОС и версии. ORVIKA не читает и не меняет эти разрешения.'},
    'apps-unused': {'title':'Удаляйте приложения, которыми больше не пользуетесь','why':'Неиспользуемые приложения могут сохранять активные сеансы, хранить данные или продолжать получать обновления и разрешения.','action':'Удалите ненужные приложения. Перед удалением экспортируйте важные данные и при необходимости отзовите доступ связанных аккаунтов.','limit':'Удаление приложения не обязательно удаляет данные, уже хранящиеся у его поставщика.'},
    'apps-sources': {'title':'Устанавливайте приложения из надёжных источников','why':'Непроверенные установщики и модифицированные приложения могут содержать нежелательный код или запрашивать избыточный доступ.','action':'Используйте официальные магазины или проверенный канал распространения разработчика. Перед установкой проверьте разработчика, запрашиваемые разрешения и историю обновлений.','limit':'Наличие приложения в официальном магазине не гарантирует его безопасность или уважение к конфиденциальности.'},
    'browsing-tracking': {'title':'Проверьте настройки приватности и отслеживания браузера','why':'Файлы cookie, разрешения сайтов и межсайтовое отслеживание могут раскрывать ваши привычки просмотра.','action':'Проверьте защиту от отслеживания, сторонние cookie, сохранённые разрешения сайтов и расширения. Удалите неизвестные или ненужные расширения.','limit':'Блокировка трекеров может нарушить работу сайтов и не делает просмотр анонимным.'},
    'browsing-sharing': {'title':'Ограничьте публикацию личной информации','why':'Публичные публикации и сведения профиля могут использоваться для выдачи себя за вас, целевого мошенничества или атак на восстановление аккаунта.','action':'Проверьте публичные поля профиля, аудиторию публикаций, передачу геолокации и старые записи. Не публикуйте документы, планы поездок и подсказки для восстановления аккаунтов.','limit':'Контент могут скопировать или архивировать до изменения настроек приватности.'},
    'browsing-network': {'title':'Используйте надёжные соединения и проверяйте сетевые запросы','why':'Поддельные Wi-Fi-порталы и незащищённые соединения могут раскрыть активность или перенаправить на обманные страницы.','action':'Предпочитайте доверенные сети, уточняйте имя сети у владельца, не выполняйте чувствительные операции в неизвестных сетях и используйте HTTPS. Отключите автоматическое подключение к незнакомым точкам доступа.','limit':'HTTPS защищает данные при передаче сайту, но не подтверждает подлинность сайта и не делает неизвестную сеть безопасной.'},
  };
  static PrivacyPractice localize(PrivacyPractice item,String code) {
    if(code!='ru') return item; final v=_data[item.id]; if(v==null)return item;
    return PrivacyPractice(id:item.id,title:v['title']!,category:item.category,why:v['why']!,action:v['action']!,limit:v['limit']!);
  }
}
